package com.relaymann.theoutlands.client;
import com.relaymann.theoutlands.TheOutlands;import com.relaymann.theoutlands.entity.*;import net.minecraft.client.model.EntityModel;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import net.minecraft.client.renderer.RenderType;import net.minecraft.client.renderer.entity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.util.Mth;import com.mojang.blaze3d.vertex.PoseStack;
final class PilgrimModel extends EntityModel<PilgrimEntity>{private final ModelPart root,head,la,ra,ll,rl;PilgrimModel(ModelPart r){super(RenderType::entityCutoutNoCull);root=r;head=r.getChild("head");la=r.getChild("la");ra=r.getChild("ra");ll=r.getChild("ll");rl=r.getChild("rl");}static LayerDefinition layer(){MeshDefinition m=new MeshDefinition();PartDefinition r=m.getRoot();r.addOrReplaceChild("head",CubeListBuilder.create().texOffs(0,0).addBox(-4,-8,-4,8,8,8).texOffs(0,16).addBox(-5,-2,-5,10,3,10),PartPose.offset(0,-17,0));r.addOrReplaceChild("body",CubeListBuilder.create().texOffs(24,0).addBox(-5,-13,-3,10,17,6).texOffs(24,24).addBox(-6,-4,-4,12,8,8),PartPose.offset(0,-3,0));r.addOrReplaceChild("la",CubeListBuilder.create().texOffs(0,30).addBox(-2,-2,-2,4,16,4),PartPose.offset(6,-12,0));r.addOrReplaceChild("ra",CubeListBuilder.create().texOffs(0,30).addBox(-2,-2,-2,4,16,4),PartPose.offset(-6,-12,0));r.addOrReplaceChild("ll",CubeListBuilder.create().texOffs(40,0).addBox(-2,0,-2,4,12,4),PartPose.offset(2,1,0));r.addOrReplaceChild("rl",CubeListBuilder.create().texOffs(40,0).addBox(-2,0,-2,4,12,4),PartPose.offset(-2,1,0));return LayerDefinition.create(m,64,128);}public void setupAnim(PilgrimEntity e,float s,float a,float age,float y,float p){head.yRot=y*Mth.DEG_TO_RAD;head.xRot=p*Mth.DEG_TO_RAD+(e.isWatching()?.16F:0);head.zRot=e.isWatching()?.10F:0;float g=Mth.cos(s*.7F)*a;la.xRot=-.2F+g*.4F;ra.xRot=-.2F-g*.4F;ll.xRot=g;rl.xRot=-g;}public void renderToBuffer(PoseStack p,com.mojang.blaze3d.vertex.VertexConsumer v,int l,int o,int c){root.render(p,v,l,o,c);}}
final class CeilingDwellerModel extends EntityModel<CeilingDwellerEntity>{private final ModelPart root,head,la,ra,ll,rl;CeilingDwellerModel(ModelPart r){super(RenderType::entityCutoutNoCull);root=r;head=r.getChild("head");la=r.getChild("la");ra=r.getChild("ra");ll=r.getChild("ll");rl=r.getChild("rl");}static LayerDefinition layer(){MeshDefinition m=new MeshDefinition();PartDefinition r=m.getRoot();r.addOrReplaceChild("head",CubeListBuilder.create().texOffs(0,0).addBox(-5,-4,-5,10,8,10).texOffs(0,18).addBox(-3,-1,-7,6,3,3),PartPose.offset(0,-4,0));r.addOrReplaceChild("body",CubeListBuilder.create().texOffs(24,0).addBox(-6,-3,-3,12,6,6),PartPose.offset(0,1,0));r.addOrReplaceChild("la",CubeListBuilder.create().texOffs(0,30).addBox(-1,-1,-2,3,13,4),PartPose.offset(6,0,0));r.addOrReplaceChild("ra",CubeListBuilder.create().texOffs(0,30).addBox(-2,-1,-2,3,13,4),PartPose.offset(-6,0,0));r.addOrReplaceChild("ll",CubeListBuilder.create().texOffs(40,0).addBox(-1,0,-2,3,12,4),PartPose.offset(4,2,0));r.addOrReplaceChild("rl",CubeListBuilder.create().texOffs(40,0).addBox(-2,0,-2,3,12,4),PartPose.offset(-4,2,0));return LayerDefinition.create(m,64,64);}public void setupAnim(CeilingDwellerEntity e,float s,float a,float age,float y,float p){head.yRot=y*Mth.DEG_TO_RAD;head.xRot=p*Mth.DEG_TO_RAD;float g=Mth.cos(s*.9F)*a;la.xRot=(e.isBraced()?-1.65F:-.5F)+g*.3F;ra.xRot=(e.isBraced()?-1.65F:-.5F)-g*.3F;ll.xRot=(e.isBraced()?-.85F:0)+g;rl.xRot=(e.isBraced()?-.85F:0)-g;head.zRot=e.isBraced()?.08F:0;}public void renderToBuffer(PoseStack p,com.mojang.blaze3d.vertex.VertexConsumer v,int l,int o,int c){root.render(p,v,l,o,c);}}
final class ColossusModel extends EntityModel<ColossusEntity>{private final ModelPart root,head,la,ra,ll,rl;ColossusModel(ModelPart r){super(RenderType::entityCutoutNoCull);root=r;head=r.getChild("head");la=r.getChild("la");ra=r.getChild("ra");ll=r.getChild("ll");rl=r.getChild("rl");}static LayerDefinition layer(){MeshDefinition m=new MeshDefinition();PartDefinition r=m.getRoot();r.addOrReplaceChild("head",CubeListBuilder.create().texOffs(0,0).addBox(-7,-12,-6,14,12,12).texOffs(0,24).addBox(-8,-5,-7,16,4,14),PartPose.offset(0,-48,0));r.addOrReplaceChild("body",CubeListBuilder.create().texOffs(24,0).addBox(-12,-24,-7,24,28,14).texOffs(24,42).addBox(-14,-19,-8,28,10,16),PartPose.offset(0,-20,0));r.addOrReplaceChild("la",CubeListBuilder.create().texOffs(0,40).addBox(-4,-4,-4,8,29,8),PartPose.offset(14,-39,0));r.addOrReplaceChild("ra",CubeListBuilder.create().texOffs(0,40).addBox(-4,-4,-4,8,29,8),PartPose.offset(-14,-39,0));r.addOrReplaceChild("ll",CubeListBuilder.create().texOffs(40,0).addBox(-5,0,-6,10,23,12),PartPose.offset(6,4,0));r.addOrReplaceChild("rl",CubeListBuilder.create().texOffs(40,0).addBox(-5,0,-6,10,23,12),PartPose.offset(-6,4,0));return LayerDefinition.create(m,128,128);}public void setupAnim(ColossusEntity e,float s,float a,float age,float y,float p){head.yRot=y*Mth.DEG_TO_RAD;head.xRot=p*Mth.DEG_TO_RAD;float g=Mth.cos(s*.32F)*a;boolean warning=e.isWindingUp();la.xRot=warning?-1.15F:-.12F+g*.12F;ra.xRot=warning?-1.15F:-.12F-g*.12F;ll.xRot=g*.25F;rl.xRot=-g*.25F;head.xRot=p*Mth.DEG_TO_RAD+(warning?.22F:0);}public void renderToBuffer(PoseStack p,com.mojang.blaze3d.vertex.VertexConsumer v,int l,int o,int c){root.render(p,v,l,o,c);}}
final class PilgrimRenderer extends MobRenderer<PilgrimEntity,PilgrimModel>{static final ModelLayerLocation LAYER=new ModelLayerLocation(ResourceLocation.fromNamespaceAndPath(TheOutlands.MOD_ID,"pilgrim"),"main");PilgrimRenderer(EntityRendererProvider.Context c){super(c,new PilgrimModel(c.bakeLayer(LAYER)),.35F);}static LayerDefinition createBodyLayer(){return PilgrimModel.layer();}public ResourceLocation getTextureLocation(PilgrimEntity e){return ResourceLocation.fromNamespaceAndPath(TheOutlands.MOD_ID,"textures/entity/pilgrim.png");}}
final class CeilingDwellerRenderer extends MobRenderer<CeilingDwellerEntity,CeilingDwellerModel>{static final ModelLayerLocation LAYER=new ModelLayerLocation(ResourceLocation.fromNamespaceAndPath(TheOutlands.MOD_ID,"ceiling_dweller"),"main");CeilingDwellerRenderer(EntityRendererProvider.Context c){super(c,new CeilingDwellerModel(c.bakeLayer(LAYER)),.38F);}static LayerDefinition createBodyLayer(){return CeilingDwellerModel.layer();}public ResourceLocation getTextureLocation(CeilingDwellerEntity e){return ResourceLocation.fromNamespaceAndPath(TheOutlands.MOD_ID,"textures/entity/ceiling_dweller.png");}}
final class ColossusRenderer extends MobRenderer<ColossusEntity,ColossusModel>{static final ModelLayerLocation LAYER=new ModelLayerLocation(ResourceLocation.fromNamespaceAndPath(TheOutlands.MOD_ID,"colossus"),"main");ColossusRenderer(EntityRendererProvider.Context c){super(c,new ColossusModel(c.bakeLayer(LAYER)),1.35F);}static LayerDefinition createBodyLayer(){return ColossusModel.layer();}public ResourceLocation getTextureLocation(ColossusEntity e){return ResourceLocation.fromNamespaceAndPath(TheOutlands.MOD_ID,"textures/entity/colossus.png");}}
